/**
 * @file Filters an autocomplete's options as someone types.
 *
 * Filtering reads the `data-*` attribute of every key `matchBy` names — `data-label` by default. The match highlight is computed separately from the option's rendered `textContent`, because an `option` snippet can render text that differs from the label, and the highlight has to sit on what's on screen.
 *
 * With `search`, the `items` are seeds. Typing filters them at once, and each search's results merge in below them. Results pass through the same filter, so the list only ever shows what the query matches.
 */
import {
  debounce,
  omitEmpty,
  toCamel,
  toKebab,
  toSlug,
} from '@splendidlabz/utils'
import { addListeners, removeListeners } from '@splendidlabz/utils/dom'
import { tick } from 'svelte'
import { SvelteMap } from 'svelte/reactivity'
import { getMatchedIndexes, hasPerfectMatch } from './matching.js'
import { match, removeAccents } from './match.js'
import {
  closeCombobox,
  isComboboxOpen,
  openCombobox,
} from './combobox.svelte.js'
import {
  addSelected,
  getOptionData,
  getValueAndLabel,
  initSelection,
  isSelected,
  sendItem,
  toggleSelected,
} from './select.svelte.js'
import {
  clearHighlight,
  getAllOptions,
  getVisibleOptions,
  selectOption,
  sortOptions,
} from './listbox.js'

/**
 * @import { Combobox } from './combobox.svelte.js'
 * @import { SelectEntry } from './select.svelte.js'
 */

/**
 * autocompleteInput
 * Narrows the options an autocomplete shows to the ones its text matches, and records what gets selected.
 *
 * @param {HTMLInputElement} node
 * @param {object} [props]
 * @param {object} [props.options]
 * @param {(query: string) => Promise<any[]>} [props.options.search] Fetches options as someone types
 * @param {number} [props.options.debounceMs] Wait before searching
 * @param {(item: any) => void} [props.options.onselect] Receives the item, or the option element
 * @param {boolean} [props.options.multiple] Let more than one option be selected
 * @param {number} [props.options.max] Most options a multi select takes
 * @param {boolean} [props.options.creatable] Accept text that matches no option
 * @param {(text: string) => string} [props.options.onCreateValue] Value for created text
 * @param {boolean} [props.options.caseSensitive] Match case while filtering and creating
 * @param {string | string[]} [props.options.matchBy] Keys typing matches against
 * @param {boolean} [props.options.openOnFocus] Open the options on focus
 * @param {SelectEntry | SelectEntry[] | null} [props.options.selected] Selection to start with
 */
export function autocompleteInput(node, props = {}) {
  const id = /** @type {string} */ (node.getAttribute('target'))
  let onselect = props.options?.onselect

  const combobox = initSelection({
    id,
    state: { searchState: 'idle' },
    options: props.options,
    defaults: { debounceMs: 250, matchBy: 'label', openOnFocus: true },
    onselect: selectItem,
  })
  combobox.options.getTypedOption = getTypedOption

  // An empty array and an empty string don't survive the merge into a registered part, so they're written here
  combobox.state.query ??= ''
  combobox.state.created ??= []

  const searchCache = new SvelteMap()

  const fetchResults = debounce(
    /** @param {string} query */
    async query => {
      let results
      try {
        results = await combobox.options.search(query)
      } catch (error) {
        // A stale query's failure shouldn't replace the current state
        if (node.value.trim() === query) combobox.state.searchState = 'failed'
        throw error
      }
      searchCache.set(query, results)

      // Someone kept typing while this was in flight
      if (node.value.trim() !== query) return
      combobox.state.results = results
      combobox.state.searchState = 'done'
      await showSearchedOptions(query)
    },
    () => combobox.options.debounceMs,
  )

  const listeners = [
    { event: 'input', node, handler: onInput },
    { event: 'focusin', node, handler: openList },
    { event: 'click', node, handler: reopenList },
  ]

  addListeners(listeners)

  return {
    /**
     * update
     * Takes the input's new options.
     *
     * @param {typeof props} [nextProps]
     */
    update(nextProps = {}) {
      onselect = nextProps.options?.onselect
      Object.assign(combobox.options, omitEmpty(nextProps.options), {
        onselect: selectItem,
      })
    },
    destroy() {
      removeListeners(listeners)
      fetchResults.cancel()
    },
  }

  /**
   * selectItem
   * Records the selection, then hands the item back to whoever owns it.
   *
   * @param {HTMLElement} option
   */
  function selectItem(option) {
    if (option.dataset.create === undefined)
      toggleSelected(combobox, getOptionData(option))
    else selectCreated()

    sendItem({ combobox, option, onselect })
  }

  /**
   * getTypedOption
   * Gets the option Enter selects when nothing is highlighted: the exact match, or the first match.
   *
   * The exact match is looked for separately because it doesn't always rank first — "Mali" sits below "Café Mali" when both match at a word start.
   *
   * Selected options are left out, so Enter on a single select showing its selection submits the form.
   *
   * @returns {HTMLElement | undefined}
   */
  function getTypedOption() {
    const { query } = combobox.state
    if (!query) return

    const { caseSensitive, matchBy } = combobox.options
    const options = getVisibleOptions(combobox.nodes.listbox).filter(
      option =>
        option.dataset.create === undefined &&
        option.getAttribute('aria-selected') !== 'true',
    )
    const exactOption = options.find(option =>
      hasPerfectMatch({
        texts: getOptionTexts({ option, matchBy }),
        query,
        caseSensitive,
      }),
    )

    return exactOption ?? options[0]
  }

  /**
   * selectCreated
   * Turns the typed text into a value, or selects the option already holding that value.
   */
  function selectCreated() {
    const text = combobox.state.query.trim()
    const value = combobox.options.onCreateValue?.(text) ?? toSlug(text)
    const twin = getAllOptions(combobox.nodes.listbox).find(
      option =>
        option.dataset.create === undefined &&
        isSameName({ combobox, one: option.dataset.value, other: value }),
    )

    if (!twin) {
      combobox.state.created.push({ value, label: text })
      addSelected(combobox, { value, label: text })
      return
    }

    // The twin can already be selected, and selecting it again would take it off
    const twinData = getOptionData(twin)
    if (isSelected({ combobox, value: twinData.value })) return
    selectOption({ listbox: combobox.nodes.listbox, option: twin })
    addSelected(combobox, twinData)
  }

  /**
   * onInput
   * Searches or filters for what was typed.
   */
  function onInput() {
    const query = node.value.trim()

    // The create option reads the query, and it renders from the options island
    combobox.state.query = query

    // The options can hydrate as their own island, after the input
    if (!combobox.nodes.listbox) return

    if (combobox.options.search) searchOptions(query)
    else showMatchingOptions({ combobox, query })
  }

  /**
   * openList
   * Opens the options on the list the field's own text gives. An empty field shows every option.
   *
   * A search field with no seed items has nothing to show, so it stays shut.
   */
  function openList() {
    if (!combobox.options.openOnFocus) return
    if (node.disabled || node.readOnly) return

    const { listbox } = combobox.nodes
    if (!listbox) return

    // Filters the way typing this text would, then opens on what's left — an exact match closes it otherwise
    const query = node.value.trim()
    combobox.state.query = query
    showMatchingOptions({ combobox, query })

    if (!getVisibleOptions(listbox).length) return
    openCombobox(combobox)
  }

  /**
   * reopenList
   * Opens the options when a field that already has focus is clicked.
   *
   * Selecting and Escape close the list without moving focus, so no focus event comes to reopen it.
   */
  function reopenList() {
    if (isComboboxOpen(combobox)) return
    openList()
  }

  /**
   * searchOptions
   * Filters what's already listed, then shows cached results for the query or searches for it.
   *
   * @param {string} query
   */
  async function searchOptions(query) {
    // Selecting dispatches `input`, which shouldn't search for what was just chosen
    if (query && query === combobox.state.selectedText) return

    const cachedResults = searchCache.get(query)

    if (!query) {
      combobox.state.results = null
      combobox.state.searchState = 'idle'
    } else if (cachedResults) {
      combobox.state.results = cachedResults
      combobox.state.searchState = 'done'
    } else {
      combobox.state.searchState = 'searching'
      fetchResults(query)
    }

    await showSearchedOptions(query)
  }

  /**
   * showSearchedOptions
   * Filters the seeds and results once Svelte has rendered them, and keeps the list open while there's a query.
   *
   * @param {string} query
   */
  async function showSearchedOptions(query) {
    await tick()

    // The options can be destroyed while Svelte renders or a search is in flight
    if (!combobox.nodes.listbox) return
    filterOptions({ combobox, query })

    // The status under the list reports the search, so the list stays up while there's a query
    if (query) openCombobox(combobox)
    else if (!combobox.options.multiple) closeCombobox(combobox)
  }
}

/**
 * mergeItems
 * Adds search results below the seed items, leaving out a result whose value a seed already holds.
 *
 * @param {object} opts
 * @param {SelectEntry[]} [opts.items] Seed items
 * @param {SelectEntry[] | null} [opts.results] What the search returned
 * @returns {SelectEntry[]}
 */
export function mergeItems({ items = [], results }) {
  if (!results) return items

  const seedValues = items.map(item => getValueAndLabel(item).value)
  const newResults = results.filter(
    result => !seedValues.includes(getValueAndLabel(result).value),
  )
  return [...items, ...newResults]
}

/**
 * orderItems
 * Sorts items by a key, or by a comparator. A key starting with `-` sorts descending.
 *
 * @typedef {string | ((one: any, other: any) => number) | null} OrderBy
 *
 * @param {object} opts
 * @param {SelectEntry[]} opts.items
 * @param {OrderBy} [opts.orderBy]
 * @returns {SelectEntry[]}
 */
export function orderItems({ items, orderBy }) {
  if (!orderBy) return items
  if (typeof orderBy === 'function') return items.toSorted(orderBy)

  const isDescending = orderBy.startsWith('-')
  const key = isDescending ? orderBy.slice(1) : orderBy
  const direction = isDescending ? -1 : 1

  return items.toSorted(
    (one, other) =>
      direction *
      compareValues(
        readItemKey({ item: one, key }),
        readItemKey({ item: other, key }),
      ),
  )
}

/**
 * getMatchData
 * Gets the `data-*` attributes an item's option needs for the keys `matchBy` names beyond its label and value.
 *
 * @param {object} opts
 * @param {SelectEntry} opts.item
 * @param {string | string[]} [opts.matchBy]
 * @returns {Record<string, string>}
 */
export function getMatchData({ item, matchBy = 'label' }) {
  const keys = [matchBy]
    .flat()
    .filter(key => key !== 'label' && key !== 'value')

  return Object.fromEntries(
    keys.map(key => [
      `data-${toKebab(key)}`,
      String(readItemKey({ item, key }) ?? ''),
    ]),
  )
}

/**
 * readItemKey
 * Reads a key off an item. A bare string is its own label and value.
 *
 * @param {object} opts
 * @param {SelectEntry} opts.item
 * @param {string} opts.key
 * @returns {any}
 */
function readItemKey({ item, key }) {
  const itemData = typeof item === 'string' ? {} : item
  return { ...itemData, ...getValueAndLabel(item) }[key]
}

/**
 * compareValues
 * Compares two values for sorting. Strings sort the way people read them, so "Item 2" comes before "Item 10".
 *
 * @param {any} one
 * @param {any} other
 * @returns {number}
 */
function compareValues(one, other) {
  if (typeof one === 'string' && typeof other === 'string')
    return one.localeCompare(other, undefined, {
      numeric: true,
      sensitivity: 'base',
    })
  if (one < other) return -1
  if (one > other) return 1
  return 0
}

/**
 * isSameName
 * Compares what two values name, so "Lead-generation" and "Lead generation" are one option rather than two.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} [opts.one]
 * @param {string} [opts.other]
 * @returns {boolean}
 */
function isSameName({ combobox, one, other }) {
  if (one === undefined || other === undefined) return false
  if (combobox.options.caseSensitive) return one.trim() === other.trim()
  return toName(one) === toName(other)
}

/**
 * toName
 * Strips what filtering already ignores — case, accents and the spaces and dashes between words.
 *
 * @param {string} value
 * @returns {string}
 */
function toName(value) {
  return toSlug(removeAccents(value.trim()))
}

/**
 * showMatchingOptions
 * Filters the options, then opens the list on what's left or closes it when nothing is left to choose.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} opts.query Typed query
 */
function showMatchingOptions({ combobox, query }) {
  filterOptions({ combobox, query })

  const { creatable, multiple } = combobox.options
  const { matchCount } = combobox.state

  // Selecting one of many clears the input, and the list has to stay up for the next one
  const canClose = !multiple

  if (!query) {
    if (canClose) closeCombobox(combobox)
    return
  }

  // With creation on, text that matches nothing still has the create option under it
  const isEmpty = !matchCount && !creatable

  // Text that reads as an option's label closes a single select, since there is nothing left to choose. An exact match on another key keeps the list up, so the option shows. Multi select keeps it up, because the match is still waiting to be selected.
  const isExact =
    !creatable &&
    hasPerfectMatch({
      texts: getVisibleOptions(combobox.nodes.listbox).map(
        option => option.dataset.label ?? '',
      ),
      query,
      caseSensitive: combobox.options.caseSensitive,
    })

  if (isEmpty || (isExact && canClose)) closeCombobox(combobox)
  else openCombobox(combobox)
}

/**
 * filterOptions
 * Hides what the query misses, ranks what's left, and paints the letters that matched.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string} opts.query Typed query
 */
function filterOptions({ combobox, query }) {
  const { input, listbox } = combobox.nodes

  // The create option carries the query as its label, so filtering it would rank it against itself
  const options = getAllOptions(listbox).filter(
    option => option.dataset.create === undefined,
  )

  const { caseSensitive, matchBy } = combobox.options
  const texts = options.map(option => getOptionTexts({ option, matchBy }))

  // The list is about to change, so the current highlight points nowhere
  clearHighlight(listbox)
  input.removeAttribute('aria-activedescendant')

  // The create option renders from the options island, which asks whether an option already says this
  combobox.state.hasExactMatch = hasPerfectMatch({
    texts: texts.flat(),
    query,
    caseSensitive,
  })

  // A created value and the create option are rendered below the list from their own blocks, so they keep their place
  const sortableOptions = options.filter(
    option => option.dataset.appended === undefined,
  )

  if (!query) {
    for (const option of options) option.hidden = false
    sortOptions({ listbox, options: sortableOptions.toSorted(byPosition) })
    paintMatches([])
    combobox.state.matchCount = options.length
    return
  }

  const matchedOptions = getMatchedIndexes({ texts, query, caseSensitive }).map(
    index => options[index],
  )

  for (const option of options) option.hidden = true
  for (const option of matchedOptions) option.hidden = false
  sortOptions({
    listbox,
    options: rankOptions({ sortableOptions, matchedOptions }),
  })
  paintMatches(
    matchedOptions.flatMap(option =>
      getTextRanges({ option, query, caseSensitive }),
    ),
  )

  // The empty status reads this, since it can't see which options are hidden
  combobox.state.matchCount = matchedOptions.length
}

/**
 * getOptionTexts
 * Reads the texts an option matches by, one per key `matchBy` names.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.option
 * @param {string | string[]} opts.matchBy
 * @returns {string[]}
 */
function getOptionTexts({ option, matchBy }) {
  return [matchBy].flat().map(key => option.dataset[toCamel(key)] ?? '')
}

/**
 * rankOptions
 * Puts the matches in front, best first, and the rest back in the order the markup wrote them.
 *
 * @param {object} opts
 * @param {HTMLElement[]} opts.sortableOptions Options that can be reordered
 * @param {HTMLElement[]} opts.matchedOptions Matched options, best first
 * @returns {HTMLElement[]}
 */
function rankOptions({ sortableOptions, matchedOptions }) {
  const matched = matchedOptions.filter(option =>
    sortableOptions.includes(option),
  )
  const rest = sortableOptions.filter(
    option => !matchedOptions.includes(option),
  )

  return [...matched, ...rest.toSorted(byPosition)]
}

/**
 * byPosition
 * Sorts options into the order the markup wrote them.
 *
 * @param {HTMLElement} one
 * @param {HTMLElement} other
 * @returns {number}
 */
function byPosition(one, other) {
  return Number(one.dataset.position) - Number(other.dataset.position)
}

/**
 * paintMatches
 * Paints the matched letters. A browser without the Highlight API filters without painting.
 *
 * @param {Range[]} ranges
 */
function paintMatches(ranges) {
  if (!CSS.highlights) return

  if (!ranges.length) {
    CSS.highlights.delete('match')
    return
  }

  CSS.highlights.set('match', new Highlight(...ranges))
}

/**
 * getTextRanges
 * Turns matched character positions into DOM ranges the Highlight API can paint.
 *
 * @typedef {{ node: Text, start: number, end: number }} TextChunk Where one text node sits in the option's text.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.option
 * @param {string} opts.query Typed query
 * @param {boolean} [opts.caseSensitive] Take case into account
 * @returns {Range[]}
 */
function getTextRanges({ option, query, caseSensitive }) {
  const positions = match({
    text: option.textContent,
    query,
    insideWords: true,
    caseSensitive,
  })
  if (!positions.length) return []

  const walker = document.createTreeWalker(option, NodeFilter.SHOW_TEXT)
  /** @type {TextChunk[]} */
  const chunks = []
  let offset = 0

  for (
    let node = /** @type {Text | null} */ (walker.nextNode());
    node;
    node = /** @type {Text | null} */ (walker.nextNode())
  ) {
    chunks.push({ node, start: offset, end: offset + node.length })
    offset += node.length
  }

  return positions.map(([start, end]) => {
    // Positions come from the same text, so a chunk always holds them
    const startChunk = /** @type {TextChunk} */ (
      chunks.find(chunk => start < chunk.end)
    )
    const endChunk = /** @type {TextChunk} */ (
      chunks.find(chunk => end <= chunk.end)
    )
    const range = new Range()
    range.setStart(startChunk.node, start - startChunk.start)
    range.setEnd(endChunk.node, end - endChunk.start)
    return range
  })
}
